sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.hc-widget {
    border-radius: 8px;
    box-shadow: 0 2px 6px rgba(0,0,0,0.05);
    font-family: 'Poppins', sans-serif;
    margin-bottom: 20px;
}

.hc-widget .panel-heading {
    background-color: #6A1B9A;
    color: #fff;
    padding: 15px;
    border-radius: 8px 8px 0 0;
}

.nav-tabs>li>a {
    font-weight: 600;
    color: #6A1B9A;
}
.nav-tabs>li.active>a {
    background-color: #6A1B9A !important;
    color: white !important;
}

sp_widget.script:
(function() {
    data.event = {};
    var sysId = $sp.getParameter('sys_id');

    if (!sysId) {
        data.error = "No Event ID provided.";
        return;
    }

    var gr = new GlideRecord('x_1790227_event_ma_event');
    if (gr.get(sysId)) {
        data.event = {
            name: gr.getValue('u_event_name'),
            date: gr.getDisplayValue('u_event_date'),
            location: gr.getValue('u_location'),
            status: gr.getDisplayValue('u_status'),
            contact_person: gr.getValue('u_contact_person'),
            contact_number: gr.getValue('u_contact_number'),
            email: gr.getValue('u_email')
        };
    } else {
        data.error = "Event not found.";
        return;
    }

    data.tasks = [];
    var taskGR = new GlideRecord('x_1790227_event_ma_event_task');
    taskGR.addQuery('u_event_id', sysId);
    taskGR.query();
    while (taskGR.next()) {
        data.tasks.push({
            name: taskGR.getValue('u_task_name'),
            assigned_to: taskGR.getDisplayValue('u_assigned_to'),
            due_date: taskGR.getDisplayValue('u_due_date'),
            status: taskGR.getDisplayValue('u_status'),
            sys_id: taskGR.getUniqueValue()
        });
    }

    data.attendees = [];
    var attendeeGR = new GlideRecord('x_1790227_event_ma_attendee');
    attendeeGR.addQuery('u_event_id', sysId);
    attendeeGR.query();
    while (attendeeGR.next()) {
        data.attendees.push({
            name: attendeeGR.getValue('u_first_name'),
            email: attendeeGR.getValue('u_email'),
            contact: attendeeGR.getValue('u_contact_number'),
            eventID: attendeeGR.getDisplayValue('u_event_id')
        });
    }

    data.vendors = [];
    var vendorGR = new GlideRecord('x_1790227_event_ma_vendor');
    vendorGR.addQuery('u_event_id', sysId);
    vendorGR.query();
    while (vendorGR.next()) {
        data.vendors.push({
            name: vendorGR.getValue('u_vendor_name'),
            contact_person: vendorGR.getValue('u_contact_person'),
            contact_number: vendorGR.getValue('u_contact_number'),
            services: vendorGR.getValue('u_services')
        });
    }

    data.budget = [];
    var budgetGR = new GlideRecord('x_1790227_event_ma_budget');
    budgetGR.addQuery('u_event_id', sysId);
    if (budgetGR.next()) {
        data.budget = {
            total: budgetGR.getValue('u_total_budget'),
            spent: budgetGR.getValue('u_amount_spent'),
            remaining: budgetGR.getValue('u_amount_remaining'),
            status: budgetGR.getDisplayValue('u_status')
        };
    }

    data.schedule = [];
    var scheduleGR = new GlideRecord('x_1790227_event_ma_schedule');
    scheduleGR.addQuery('u_event_id', sysId);
    scheduleGR.query();
    while (scheduleGR.next()) {
        data.schedule.push({
            activity: scheduleGR.getValue('u_activity_name'),
            start: scheduleGR.getDisplayValue('u_start_time'),
            end: scheduleGR.getDisplayValue('u_end_time'),
            location: scheduleGR.getValue('u_location')
        });
    }

    data.feedback = [];
    var feedbackGR = new GlideRecord('x_1790227_event_ma_feedback');
    feedbackGR.addQuery('u_event_id', sysId);
    feedbackGR.query();
    while (feedbackGR.next()) {
        data.feedback.push({
            attendee: feedbackGR.getDisplayValue('u_attendee'),
            rating: feedbackGR.getValue('u_rating'),
            comments: feedbackGR.getValue('u_comments')
        });
    }
})();
